<?php
namespace Modules\PriyasaCore\Jobs;
use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Modules\PriyasaCore\Models\CommerceConversationMessage; use Modules\PriyasaCore\Services\MetaWhatsAppMessageService;
class SendWhatsAppInteractive implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public $tries=5; public function __construct(public int $messageId, public string $phone, public array $payload){} public function backoff(){return [10,30,120,600];} public function handle(MetaWhatsAppMessageService $meta){$m=CommerceConversationMessage::find($this->messageId); if(!$m || $m->provider_message_id)return; $result=match($this->payload['type']??'text'){ 'buttons'=>$meta->sendInteractiveButtons($this->phone,$this->payload['body'],$this->payload['buttons']??[],$this->payload['header']??null,$this->payload['footer']??null), 'list'=>$meta->sendList($this->phone,$this->payload['body'],$this->payload['button_text']??'Select',$this->payload['sections']??[],$this->payload['header']??null,$this->payload['footer']??null), 'image'=>$meta->sendImage($this->phone,$this->payload['url'],$this->payload['caption']??null), 'template'=>$meta->sendTemplate($this->phone,$this->payload['name'],$this->payload['language']??'en',$this->payload['components']??[]), 'product'=>$meta->sendProduct($this->phone,$this->payload['catalog_id'],$this->payload['product_retailer_id'],$this->payload['body']??null,$this->payload['footer']??null), default=>$meta->sendImage($this->phone,$this->payload['url']??'',null)}; $m->update(['provider_message_id'=>$result['messages'][0]['id']??null,'provider_status'=>'accepted','sent_at'=>now(),'metadata'=>array_merge($m->metadata??[],['meta_response'=>$result])]);}}
